(x, y, t) => {
  const cx = 240, cy = 120;
  const warp1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.22)*12;
  const warp1y = Math.cos(y*0.02-t*0.28)*16 + Math.sin(x*0.016+t*0.33)*11;
  const warp2x = Math.sin((x+y)*0.01+t*0.15)*8;
  const warp2y = Math.cos((x-y)*0.012-t*0.18)*8;
  const sx = x + warp1x + warp2x, sy = y + warp1y + warp2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.7],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*55, 0.11, 2.1, 0.6],
    [400+Math.cos(t*0.38+2)*60, 200+Math.sin(t*0.48+4)*50, 0.075, 2.4, 1.3]
  ];
  let aS = 0, iS = 0, cross = 0;
  const dists = [];
  for (const [sX, sY, f, sp, amp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    dists.push(d);
    aS += Math.sin(d*f - t*sp) * amp;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * amp;
  }
  for (let i = 0; i < dists.length; i++) {
    for (let j = i+1; j < dists.length; j++) {
      cross += Math.sin(dists[i]*0.05 + dists[j]*0.05 - t*1.3) * 0.12;
      cross += Math.cos(dists[i]*0.04 - dists[j]*0.06 + t*0.9) * 0.08;
    }
  }
  const act = aS/src.length, inh = iS/src.length;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.07*Math.cos(t*0.1)+sy*0.05*Math.sin(t*0.13)+t*1.7)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.08+ang*2-t*2.5)*0.15;
  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral + cross)*2.2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.sin(sx*0.35+t*3)*Math.sin(sy*0.35-t*2.5)*0.08*Math.abs(reaction);
  const blend = reaction*0.65 + cell*0.2 + micro*0.15;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,45],[10,45,85],[15,90,120],[25,140,135],[50,175,145],
    [160,200,90],[220,190,60],[230,140,55],[210,85,60],[175,50,70],
    [110,30,60],[60,18,48],[5,12,45]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sm = f*f*(3-2*f);
  const lum = 0.78 + Math.sin(reaction*Math.PI)*0.22;
  const edge = Math.abs(reaction)>0.65?1.12:Math.abs(reaction)>0.3?1.0:0.92;
  const glow = Math.max(0, 1-Math.abs(reaction)*2)*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*lum*edge + glow*30)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*lum*edge + glow*40)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*lum*edge + glow*60)|0)
  ];
}
